SET NOCOUNT ON;
SELECT DB_NAME() AS database_name, SYSUTCDATETIME() AS checked_at_utc;
SELECT id, horse_code, name, lifecycle, health_status FROM dbo.horse WHERE id=7;
SELECT id, horse_id, status, closed_at FROM dbo.medical_case WHERE id=7;
SELECT id, medical_case_id, exam_type, recovery_outcome, health_status_set FROM dbo.veterinary_examination WHERE medical_case_id=7 ORDER BY id;
SELECT id, horse_id, status, medical_case_id FROM dbo.incident WHERE id=9;
SELECT id, horse_id, status, closed_at FROM dbo.medical_case WHERE id=8;
SELECT id, horse_id, status, closed_at FROM dbo.medical_case WHERE id=9;
SELECT id, horse_id, status, medical_case_id FROM dbo.incident WHERE id IN (10,11) ORDER BY id;
SELECT id, medical_case_id, lifted_at FROM dbo.medical_restriction WHERE medical_case_id=7;
SELECT id, horse_id, treatment_plan_id, completed_by_user_id, completed_at, scheduled_slot FROM dbo.care_task WHERE horse_id=7 ORDER BY id;
SELECT id, name, unit, current_quantity FROM dbo.inventory_item WHERE id=1;
SELECT id, change_quantity, recorded_by_user_id FROM dbo.stock_movement WHERE inventory_item_id=1 ORDER BY id;
SELECT id, quantity, requested_by_user_id FROM dbo.replenishment_request WHERE inventory_item_id=1;
SELECT id, horse_code, name, lifecycle FROM dbo.horse WHERE id<=6 ORDER BY id;
SELECT COUNT(*) AS accounts_count FROM dbo.app_user;
IF NOT EXISTS(SELECT 1 FROM dbo.medical_case WHERE id=7 AND horse_id=7 AND status='CLOSED' AND closed_at IS NOT NULL) THROW 51000,'QA_CASE_NOT_CLOSED',1;
IF NOT EXISTS(SELECT 1 FROM dbo.incident WHERE id=9 AND medical_case_id=7 AND status='RESOLVED') THROW 51000,'QA_INCIDENT_NOT_RESOLVED',1;
IF NOT EXISTS(SELECT 1 FROM dbo.care_task WHERE id=6 AND completed_by_user_id=6 AND completed_at IS NOT NULL) THROW 51000,'QA_GROOM_TASK_NOT_COMPLETED',1;
IF EXISTS(SELECT 1 FROM dbo.medical_restriction WHERE medical_case_id=7 AND lifted_at IS NULL) THROW 51000,'QA_RESTRICTION_NOT_LIFTED',1;
IF NOT EXISTS(SELECT 1 FROM dbo.inventory_item WHERE id=1 AND current_quantity=13) THROW 51000,'QA_STOCK_BALANCE_MISMATCH',1;
IF (SELECT COUNT(*) FROM dbo.stock_movement WHERE inventory_item_id=1)<>2 THROW 51000,'QA_STOCK_HISTORY_MISMATCH',1;
IF NOT EXISTS(SELECT 1 FROM dbo.replenishment_request WHERE inventory_item_id=1 AND quantity=3 AND requested_by_user_id=6) THROW 51000,'QA_REPLENISHMENT_MISSING',1;
IF (SELECT COUNT(*) FROM dbo.app_user)<>19 THROW 51000,'ACCOUNT_COUNT_CHANGED',1;
IF NOT EXISTS(SELECT 1 FROM dbo.medical_case WHERE id=8 AND horse_id=7 AND status='CLOSED') THROW 51000,'QA_MINIMAL_CASE_NOT_CLOSED',1;
IF EXISTS(SELECT 1 FROM dbo.treatment_plan WHERE medical_case_id=8) THROW 51000,'QA_MINIMAL_CASE_UNEXPECTED_PLAN',1;
IF (SELECT COUNT(*) FROM dbo.incident WHERE id IN (10,11) AND horse_id=7 AND status='RESOLVED')<>2 THROW 51000,'QA_TRIAGE_NOT_RESOLVED',1;
IF NOT EXISTS(SELECT 1 FROM dbo.medical_case WHERE id=9 AND horse_id=7 AND status='CLOSED') THROW 51000,'QA_INDEPENDENT_CASE_NOT_CLOSED',1;
IF NOT EXISTS(SELECT 1 FROM dbo.care_task WHERE id=5 AND horse_id=7 AND completed_at IS NULL AND scheduled_slot='23:59') THROW 51000,'QA_FUTURE_CARE_CHANGED',1;
SELECT 'SQL_READBACK_PASS' AS result;
